('webform.webform.template_issue','a:22:{s:4:\"uuid\";s:36:\"caa2c858-eb62-4ea8-b9c4-bc74fa590e1b\";s:8:\"langcode\";s:2:\"en\";s:6:\"status\";s:6:\"closed\";s:12:\"dependencies\";a:1:{s:8:\"enforced\";a:1:{s:6:\"module\";a:1:{i:0;s:17:\"webform_templates\";}}}s:5:\"_core\";a:1:{s:19:\"default_config_hash\";s:43:\"jQo0GMZZDdlAxVTqcuM4Ew21jwXY7FPB-CTpL17Mryk\";}s:6:\"weight\";i:0;s:4:\"open\";N;s:5:\"close\";N;s:3:\"uid\";N;s:8:\"template\";b:1;s:7:\"archive\";b:0;s:2:\"id\";s:14:\"template_issue\";s:5:\"title\";s:5:\"Issue\";s:11:\"description\";s:26:\"An issue webform template.\";s:10:\"categories\";a:0:{}s:8:\"elements\";s:3507:\"meta_data_details:\n  \'#title\': \'Issue Meta Data\'\n  \'#type\': details\n  \'#open\': true\n  meta_data_01:\n    \'#type\': webform_flexbox\n    title:\n      \'#type\': textfield\n      \'#title\': Title\n      \'#required\': true\n    project:\n      \'#type\': select\n      \'#title\': Project\n      \'#required\': true\n      \'#options\':\n        \'Project I\': \'Project I\'\n        \'Project II\': \'Project II\'\n        \'Project III\': \'Project III\'\n  meta_data_02:\n    \'#type\': webform_flexbox\n    category:\n      \'#type\': select\n      \'#title\': Category\n      \'#required\': true\n      \'#options\':\n        \'Bug report\': \'Bug report\'\n        Task: Task\n        \'Feature request\': \'Feature request\'\n        \'Support request\': \'Support request\'\n        Plan: Plan\n    priority:\n      \'#type\': select\n      \'#title\': Priority\n      \'#required\': true\n      \'#options\':\n        4: Critical\n        3: Major\n        2: Normal\n        1: Minor\n    status:\n      \'#type\': webform_select_other\n      \'#title\': Status\n      \'#required\': true\n      \'#options\':\n        Active: Active\n        \'Needs work\': \'Needs work\'\n        \'Needs review\': \'Needs review\'\n        \'Reviewed & tested by the community\': \'Reviewed & tested by the community\'\n        \'Patch (to be ported)\': \'Patch (to be ported)\'\n        Fixed: Fixed\n        Postponed: Postponed\n        \'Postponed (maintainer needs more info)\': \'Postponed (maintainer needs more info)\'\n        \'Closed (duplicate)\': \'Closed (duplicate)\'\n        \'Closed (won\'\'t fix)\': \'Closed (won\'\'t fix)\'\n        \'Closed (works as designed)\': \'Closed (works as designed)\'\n        \'Closed (cannot reproduce)\': \'Closed (cannot reproduce)\'\n        \'Closed (outdated)\': \'Closed (outdated)\'\n    version:\n      \'#type\': webform_autocomplete\n      \'#title\': Version\n      \'#required\': true\n      \'#autocomplete_existing\': true\n    component:\n      \'#type\': webform_select_other\n      \'#title\': Component\n      \'#required\': true\n      \'#options\':\n        Code: Code\n        Documentation: Documentation\n        Miscellaneous: Miscellaneous\n        \'User interface\': \'User interface\'\n    assigned:\n      \'#type\': entity_autocomplete\n      \'#title\': Assigned\n      \'#target_type\': user\n      \'#selection_handler\': \'default:user\'\n      \'#selection_settings\':\n        include_anonymous: false\n  meta_data_03:\n    \'#type\': webform_flexbox\n    tags:\n      \'#type\': entity_autocomplete\n      \'#title\': \'Issue Tags\'\n      \'#description\': \'Do <strong>NOT</strong> use tags for adding random keywords or duplicating any other fields.  Separate terms with a comma, not a space.\'\n      \'#tags\': true\n      \'#target_type\': taxonomy_term\n      \'#selection_handler\': \'default:taxonomy_term\'\n      \'#selection_settings\':\n        target_bundles:\n          tags: tags\n        auto_create: 1\n        auto_create_bundle: tags\nsummary_and_relationships_details:\n  \'#title\': \'Issue Summary\'\n  \'#type\': details\n  \'#open\': true\n  summary:\n    \'#type\': text_format\n    \'#title\': Summary\n    \'#description\': \'An issue summary is a concise overview of a full issue report. Issue summaries need to be written if the iss